-- Rollback 240: remove the ten inserted BECE beta questions; preserve remediation history.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _expected_240 (question_id TEXT PRIMARY KEY, topic_id TEXT NOT NULL, subject_id TEXT NOT NULL, exam_type_id TEXT NOT NULL, question_text TEXT NOT NULL, question_type TEXT NOT NULL, options TEXT NOT NULL, correct_answer TEXT NOT NULL, explanation TEXT NOT NULL, difficulty TEXT NOT NULL, points INTEGER NOT NULL, marks INTEGER NOT NULL, time_limit INTEGER NOT NULL, command_word TEXT NOT NULL, assessment_objective TEXT NOT NULL);
DELETE FROM _expected_240;
INSERT INTO _expected_240(question_id,topic_id,subject_id,exam_type_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit,command_word,assessment_objective) VALUES
  ('q_bece_bdt_gap_b001_031','topic_bece_bdt_entrepreneurship','subj_bece_bdt','exam_bece','What does a value proposition explain?','multiple_choice','["A. Only the owner’s hobbies","B. Why defects should be ignored","C. The useful benefit that makes the product worth choosing","D. How to hide price"]','C','A value proposition connects product features to a customer need and distinguishes the offer from available alternatives. Therefore the correct answer is C: The useful benefit that makes the product worth choosing.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_bdt_gap_b001_032','topic_bece_bdt_entrepreneurship','subj_bece_bdt','exam_bece','Why record daily sales and expenses separately?','multiple_choice','["A. To make receipts unverifiable","B. To mix household money","C. To stop returns","D. To track cash movement and performance accurately"]','D','Separate records show what the business earned and spent, support profit checks and make unusual losses easier to investigate. Therefore the correct answer is D: To track cash movement and performance accurately.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_bdt_gap_b001_033','topic_bece_bdt_entrepreneurship','subj_bece_bdt','exam_bece','What is the break-even point?','multiple_choice','["A. The sales level where total revenue equals total cost","B. When nobody knows the product","C. The highest imagined price","D. When every cost is zero"]','A','At break-even the enterprise covers fixed and variable costs but has not made a profit, so later sales can contribute to profit. Therefore the correct answer is A: The sales level where total revenue equals total cost.','easy',1,1,90,'Define','AO1'),
  ('q_bece_bdt_gap_b001_034','topic_bece_bdt_entrepreneurship','subj_bece_bdt','exam_bece','Which pricing approach is most responsible?','multiple_choice','["A. Copy an unrelated high price","B. Calculate costs, customer value and realistic market prices","C. Ignore labour and materials","D. Change prices randomly"]','B','Sound pricing covers relevant costs, reflects product value and remains credible against alternatives while sustaining quality. Therefore the correct answer is B: Calculate costs, customer value and realistic market prices.','hard',1,1,90,'Evaluate','AO3'),
  ('q_bece_bdt_gap_b001_035','topic_bece_bdt_entrepreneurship','subj_bece_bdt','exam_bece','How can customer feedback improve a product?','multiple_choice','["A. Prove complaints are dishonest","B. Remove the need to test","C. Reveal defects and unmet needs for the next revision","D. Guarantee one design suits all"]','C','Structured feedback identifies recurring user problems and priorities that the maker can verify before improving the design. Therefore the correct answer is C: Reveal defects and unmet needs for the next revision.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_bdt_gap_b001_036','topic_bece_bdt_entrepreneurship','subj_bece_bdt','exam_bece','What is the purpose of quality control?','multiple_choice','["A. Hide defective units","B. Check that outputs consistently meet agreed requirements","C. Increase unmeasured waste","D. Avoid dimensions"]','B','Quality control compares work with defined standards at useful stages, allowing faults to be corrected before products reach customers. Therefore the correct answer is B: Check that outputs consistently meet agreed requirements.','medium',1,1,90,'Explain','AO2'),
  ('q_bece_bdt_gap_b001_037','topic_bece_bdt_entrepreneurship','subj_bece_bdt','exam_bece','Why keep business and household money separate?','multiple_choice','["A. To prevent budgets","B. To hide withdrawals","C. To know the enterprise’s true cash position","D. To remove receipts"]','C','Separating funds makes income, costs and drawings traceable and helps the owner decide what the enterprise can safely spend. Therefore the correct answer is C: To know the enterprise’s true cash position.','medium',1,1,90,'Interpret','AO2'),
  ('q_bece_bdt_gap_b001_038','topic_bece_bdt_entrepreneurship','subj_bece_bdt','exam_bece','What does positive cash flow mean for a period?','multiple_choice','["A. More cash entered the business than left it","B. There were no sales","C. All sales were unpaid","D. Payment dates were ignored"]','A','Positive cash flow means receipts exceeded payments for that period, although profitability and future obligations still need review. Therefore the correct answer is A: More cash entered the business than left it.','easy',1,1,90,'Interpret','AO1'),
  ('q_bece_bdt_gap_b001_039','topic_bece_bdt_entrepreneurship','subj_bece_bdt','exam_bece','Which advertising statement is ethical?','multiple_choice','["A. A false no-failure claim","B. A hidden charge","C. A fabricated endorsement","D. A truthful description of tested features and actual price"]','D','Ethical promotion gives customers accurate material information and avoids deceptive claims, supporting informed choice and trust. Therefore the correct answer is D: A truthful description of tested features and actual price.','hard',1,1,90,'Explain','AO3'),
  ('q_bece_bdt_gap_b001_040','topic_bece_bdt_entrepreneurship','subj_bece_bdt','exam_bece','Why prepare a business plan before seeking a small loan?','multiple_choice','["A. To guarantee approval","B. To replace records","C. To explain market, operations, costs, risks and repayment capacity","D. To prove conditions never change"]','C','A business plan organizes enterprise assumptions and helps owner and lender judge whether expected cash flows support repayment. Therefore the correct answer is C: To explain market, operations, costs, risks and repayment capacity.','hard',1,1,90,'Explain','AO3');
CREATE TABLE IF NOT EXISTS _rollback_240_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _rollback_240_guard;
INSERT INTO _rollback_240_guard(valid) SELECT CASE WHEN
  NOT EXISTS (SELECT 1 FROM questions q JOIN _expected_240 e ON e.question_id=q.id WHERE NOT (q.id IS e.question_id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective))
  AND NOT EXISTS (SELECT 1 FROM question_content_releases r JOIN _expected_240 e ON e.question_id=r.question_id WHERE NOT (r.batch_id IS 'bece-bdt-gap-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana’s published NaCCA Common Core Programme curricula; not official WAEC or NaCCA examination material.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1))
  AND NOT EXISTS (SELECT 1 FROM question_bank_remediation_log l JOIN _expected_240 e ON e.question_id=l.entity_id WHERE l.migration_id='240_bece_bdt_gap_beta_part_4' AND NOT (l.migration_id IS '240_bece_bdt_gap_beta_part_4' AND l.entity_type IS 'question' AND l.field_name IS 'insert' AND l.old_value IS NULL AND l.new_value IS 'bece-bdt-gap-beta-001'))
  AND (((SELECT COUNT(*) FROM questions q JOIN _expected_240 e ON e.question_id=q.id WHERE q.id IS e.question_id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective)=10 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _expected_240 e ON e.question_id=r.question_id WHERE r.batch_id IS 'bece-bdt-gap-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana’s published NaCCA Common Core Programme curricula; not official WAEC or NaCCA examination material.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)=10 AND (SELECT COUNT(*) FROM question_bank_remediation_log l JOIN _expected_240 e ON e.question_id=l.entity_id WHERE l.migration_id IS '240_bece_bdt_gap_beta_part_4' AND l.entity_type IS 'question' AND l.field_name IS 'insert' AND l.old_value IS NULL AND l.new_value IS 'bece-bdt-gap-beta-001')=10)
    OR ((SELECT COUNT(*) FROM questions q JOIN _expected_240 e ON e.question_id=q.id)=0 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _expected_240 e ON e.question_id=r.question_id)=0 AND (SELECT COUNT(*) FROM question_bank_remediation_log l JOIN _expected_240 e ON e.question_id=l.entity_id WHERE l.migration_id='240_bece_bdt_gap_beta_part_4') IN (0,10)))
THEN 1 ELSE 0 END;
DELETE FROM questions WHERE id IN (SELECT question_id FROM _expected_240);
INSERT INTO _rollback_240_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _expected_240 e ON e.question_id=q.id)=0 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _expected_240 e ON e.question_id=r.question_id)=0 THEN 1 ELSE 0 END;
DROP TABLE _expected_240;
DROP TABLE _rollback_240_guard;
